/*
 * prog29_roman_numeral_parser.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 * The program expects a single command‑line argument that should be a
 * Roman numeral (case‑insensitive).  If the argument is a valid Roman
 * numeral the program prints its integer value, otherwise it prints
 * the literal string "INVALID".
 *
 * The implementation follows the logic that was recovered from the
 * disassembly:
 *   • The input is limited to 63 characters.
 *   • It is converted to upper‑case.
 *   • The numeral is parsed by repeatedly matching the symbols
 *     {"M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"}
 *     in that order, adding the corresponding values
 *     {1000,900,500,400,100,90,50,40,10,9,5,4,1}.
 *   • While parsing the matched symbols are concatenated into a
 *     temporary buffer; after the scan the buffer must be identical
 *     to the upper‑cased input – this guarantees that the input is
 *     a *canonical* Roman numeral (e.g. "IIV" is rejected).
 *   • On success the integer value is printed with "%d\n".
 *   • On any error the program prints "INVALID".
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 63          /* same limit used by the original binary */

/* Roman symbols in descending order together with their values */
static const char *const SYMS[] = {
    "M",  "CM", "D",  "CD", "C",
    "XC", "L",  "XL", "X",  "IX",
    "V",  "IV", "I"
};

static const int VALUES[] = {
    1000, 900, 500, 400, 100,
     90,   50,  40,  10,   9,
      5,    4,   1
};

int main(int argc, char *argv[])
{
    /* No argument → INVALID (the original program does the same) */
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *src = argv[1];
    size_t len = strlen(src);

    /* Length checks – the original binary rejects empty strings
       and strings longer than 63 characters. */
    if (len == 0 || len > MAX_INPUT) {
        puts("INVALID");
        return 0;
    }

    /* -----------------------------------------------------------------
       1. Build an upper‑case copy of the input (the original stores it
          in a global buffer called main_upper).
       ----------------------------------------------------------------- */
    char upper[MAX_INPUT + 1];
    for (size_t i = 0; i < len; ++i) {
        char c = src[i];
        if ('a' <= c && c <= 'z')
            c = (char)(c - 'a' + 'A');
        upper[i] = c;
    }
    upper[len] = '\0';

    /* -----------------------------------------------------------------
       2. Parse the numeral.
          The original code walks through the SYMS array, repeatedly
          matching each symbol with strncmp and adding the associated
          value.  While doing so it copies the matched symbols into a
          temporary buffer (local_58) which is later compared with the
          original upper‑cased string.
       ----------------------------------------------------------------- */
    char reconstructed[MAX_INPUT + 1] = {0};
    size_t recon_len = 0;
    size_t pos = 0;          /* current position in upper */
    int total = 0;           /* accumulated integer value */

    for (size_t i = 0; i < sizeof(SYMS) / sizeof(SYMS[0]); ++i) {
        const char *sym = SYMS[i];
        size_t sym_len = strlen(sym);

        while (pos + sym_len <= len && strncmp(upper + pos, sym, sym_len) == 0) {
            total += VALUES[i];

            /* Append the matched symbol to the reconstructed string */
            memcpy(reconstructed + recon_len, sym, sym_len);
            recon_len += sym_len;
            reconstructed[recon_len] = '\0';

            pos += sym_len;
        }
    }

    /* -----------------------------------------------------------------
       3. Validation.
          The original program checks two conditions:
            a) the whole input was consumed,
            b) the reconstructed string equals the upper‑cased input.
          If either fails the program prints "INVALID".
       ----------------------------------------------------------------- */
    if (pos == len && strcmp(reconstructed, upper) == 0) {
        printf("%d\n", total);
    } else {
        puts("INVALID");
    }

    return 0;
}
